                    </div>
                 </div>

                 <div className="pt-6 border-t space-y-6">
                    <h4 className="text-[10px] font-black text-blue-600 uppercase tracking-[0.2em]">Guardian Information</h4>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
