const getCurrentAcademicCycle = () => {
  const now = new Date();
  const year = now.getFullYear();
  const month = now.getMonth(); // 0-indexed
  let term = 1;
  if (month >= 4 && month <= 7) term = 2;
  else if (month >= 8) term = 3;
  return { year, term };
